/**
 * Lazy loader for the vendored `allw-wasm` core (the only place the SDK touches Rust).
 *
 * All security-critical logic — request-hash canonicalization, JWE encryption, verdict
 * verification — lives once in `allw-core` and is reached here through the WASM surface
 * (`docs/architecture.md`: WASM-local is a hard constraint; no `napi`/native binary). This module
 * only orchestrates loading; it adds no crypto of its own.
 *
 * The vendored `--target web` glue (`packages/sdk/vendor/allw-wasm`, generated by
 * `pnpm run build:wasm` from the repo root and gitignored) is loaded synchronously by compiling
 * the `.wasm` bytes into a `WebAssembly.Module` and calling `initSync`. **This loader is Node-only**
 * — it reads the bytes from disk via `node:fs`. The same `--target web` artifact is itself
 * browser/worker-capable, but a web host needs a different byte source (e.g. `fetch` + `initSync`);
 * that loader is out of scope here. Mirrors `packages/sdk/test/wasm.test.mjs`.
 *
 * @see ../../../docs/architecture.md (WASM-local constraint)
 * @see ../vendor/allw-wasm/allw_wasm.d.ts (the generated FFI surface)
 */

import { existsSync, readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { MAX_ESCAPED_DIAGNOSTIC_CHARS, escapeToPrintableAscii } from "./printable-ascii.js";

/**
 * The subset of the `allw-wasm` FFI the SDK calls. Every function takes and returns JSON strings
 * (or base64url strings) and **throws** on any error (malformed input, failed verification) —
 * matching the fail-closed invariant at the language boundary (`docs/contract.md` §Invariants #6).
 *
 * This interface is a hand-maintained mirror of the generated `allw_wasm.d.ts` so that the SDK's
 * own types do not depend on the gitignored vendor directory being present at type-check time of
 * downstream consumers; the loader validates the runtime shape against it.
 */
export interface AllwWasm {
  /**
   * Computes the WYSIWYS `request_hash` (base64url-unpadded 32 bytes) for an `ApprovalContext`
   * JSON bound to `expiresAt` (Unix ms). Reproduces the Rust `request-hash/v3` value exactly.
   * The v3 canonical contract removes risk/policy-only action slots, uses ActionRecord schema 2,
   * and binds reversibility only when the caller supplies an assertion. Prior v2 receipts cannot
   * verify as current-format receipts.
   */
  compute_request_hash(contextJson: string, expiresAt: number): string;
  /**
   * Encrypts an `ApprovalContext` JSON to one or more recipient devices, returning the
   * General-JSON-Serialization JWE string for the envelope's `context_ciphertext`.
   *
   * `recipientsJson` is a JSON array of `{ device_id, public_key_b64 }` (X25519 pubkeys).
   */
  encrypt_context(contextJson: string, recipientsJson: string): string;
  /**
   * Encrypts an `ApprovalContext` JSON to exactly the devices root-signed account state selects
   * (core `seal_context_for_account_state`), returning `{ ciphertext, sequence }` JSON. Recipient
   * keys never cross into JavaScript. `minSequence` is the caller's persisted floor, or
   * `undefined`. **Throws** (nothing encrypted) on any selection failure.
   */
  seal_context_for_account_state(
    contextJson: string,
    accountStatesJson: string,
    expectedAccountId: string,
    accountRootPubkeyB64: string,
    nowMs: number,
    minSequence?: number,
  ): string;
  /**
   * Verifies a `Verdict` JSON against the request, the human-shown context, and the approver's
   * account-root Ed25519 public key (base64url). Returns
   * `{ approved: true, device_id, decided_at, nonce_b64, note? }` JSON on success; **throws** on any
   * verification failure. The optional string `note` comes verbatim from the authenticated signed
   * claims, for audit consumers; it is omitted when no note was signed.
   * An authenticated non-approval throws an `Error` with own properties
   * `kind: "not_approved"` and `decision` (`denied`/`expired`/`aborted`, from the signed claims);
   * every other failure throws an `Error` with no `kind`. Never classify by the message: untrusted
   * input is echoed into it.
   */
  verify_verdict(
    verdictJson: string,
    requestJson: string,
    contextJson: string,
    approverRootPubkeyB64: string,
    nowMs: number,
    expectedAccountId?: string | null,
  ): string;
  /**
   * Verifies a verdict and rejects it when the signing device appears revoked in the
   * highest-sequence valid account state. `accountStatesJson` is a JSON array of compact
   * root-signed account-state JWS strings. Throws exactly like {@link AllwWasm.verify_verdict},
   * including the structured `kind: "not_approved"` error.
   */
  verify_verdict_with_account_states(
    verdictJson: string,
    requestJson: string,
    contextJson: string,
    approverRootPubkeyB64: string,
    nowMs: number,
    accountStatesJson: string,
    expectedAccountId?: string | null,
  ): string;
  /** Sign a root-authored account-state JSON document, returning a compact account-state JWS. */
  sign_account_state(stateJson: string, accountRootSeedB64: string): string;
  /** Verify a compact account-state JWS and return the verified AccountState JSON. */
  verify_account_state(
    accountStateJws: string,
    expectedAccountId: string,
    accountRootPubkeyB64: string,
  ): string;
  /**
   * Resolves the device ids revoked in the highest-sequence valid account state(s), returning a
   * JSON array of device id strings (empty when `accountStatesJson` is `"[]"`). Used to filter
   * revoked devices out of the JWE recipient set **before** encrypting a new request (issue #204
   * fix 1) — the parse/verify/resolve logic stays in core; the caller only drops matching ids.
   */
  revoked_device_ids(
    accountStatesJson: string,
    expectedAccountId: string,
    accountRootPubkeyB64: string,
  ): string;
  /**
   * Derive the self-certifying account id for an account-root public key (base64url-unpadded).
   * **Throws** when the key is not base64url-unpadded, not exactly 32 bytes, or not a valid
   * Ed25519 point.
   */
  account_id_for_root(accountRootPubkeyB64: string): string;
  /**
   * Check that `accountId` is exactly the id derived from `accountRootPubkeyB64`. **Throws** on a
   * malformed key or a mismatch.
   */
  check_account_id_for_root(accountId: string, accountRootPubkeyB64: string): void;
  /** Derive the Ed25519 public key for a 32-byte signing seed (base64url). */
  ed25519_public_key(seedB64: string): string;
  /**
   * Build an ActionRecord JSON for a shell command using the core T1 command parser. **Throws** an
   * `Error` whose `kind` is the core's code: `invalid_shell_syntax`, or, for a line that runs no
   * program (#376), `no_command`, `no_program` or `empty_program`.
   */
  action_from_command(commandLine: string, cwd?: string | null): string;
  /**
   * Build an ActionRecord JSON for a **PowerShell** command line (the `command` surface). `raw` is
   * the exact line and argv is its whitespace split. No danger tier is assigned. Never throws for PowerShell syntax; throws
   * only for a line that runs no program (#376), with a `kind` as `action_from_command`.
   */
  action_from_powershell_command(commandLine: string, cwd?: string | null): string;
  /**
   * Build an ActionRecord JSON from a **canonical, pre-tokenized** argv (JSON array of strings).
   * For callers that hold the exact token vector that will execute and must bind it verbatim —
   * re-tokenizing their command text would risk binding different tokens than the ones that run
   * (`docs/openclaw-integration.md` §5.1). `raw` is the original command text (recorded verbatim
   * and the only source of `env_refs`; never re-tokenized). **Throws** for malformed JSON (no
   * `kind`), and for an argv with no program (#376) with a `kind` as `action_from_command`:
   * `no_command` (empty), `empty_program`, or `no_program` (only assignments).
   */
  action_from_argv(argvJson: string, raw?: string | null, cwd?: string | null): string;
  /**
   * Build an ActionRecord JSON for an agent-runtime/plugin-owned tool call (`agent_tool_call`
   * surface). `server` holds the gating provider identity; `paramsJson` is omitted when the caller
   * has no structured parameters to offer.
   */
  action_from_agent_tool_call(server: string, tool: string, paramsJson?: string | null): string;
  /**
   * Build an ActionRecord JSON for an agent-runtime/plugin-owned tool call (`agent_tool_call`
   * surface), binding `raw` **verbatim** instead of the synthesized `<server>.<tool>(...)`
   * display. Use this when the caller already holds human-authored reviewer prose for the action
   * (`docs/openclaw-integration.md` §5.2: `syntactic.raw` = `description`, plus `detail` when
   * present); use {@link action_from_agent_tool_call} when no such prose exists.
   */
  action_from_agent_tool_call_with_raw(
    server: string,
    tool: string,
    raw: string,
    paramsJson?: string | null,
  ): string;
}

/** The init surface the generated `--target web` glue exposes alongside the FFI functions. */
interface WasmGlue extends AllwWasm {
  initSync(input: { module: WebAssembly.Module }): unknown;
}

/** Resolve the vendored glue directory relative to this compiled module. */
function vendorDir(): string {
  // Compiled to `dist/wasm.js`; the vendor dir is a sibling of `dist` under the package root.
  const here = dirname(fileURLToPath(import.meta.url));
  return join(here, "..", "vendor", "allw-wasm");
}

let cached: AllwWasm | null = null;

/** Initialize already-imported glue from the vendored bytes and memoize it. */
function initGlue(glue: WasmGlue, dir: string): AllwWasm {
  const bytes = readFileSync(join(dir, "allw_wasm_bg.wasm"));
  const module = new WebAssembly.Module(bytes);
  glue.initSync({ module });
  cached = glue;
  return glue;
}

/** The vendored files the loader reads; if any is missing, the core was never built here. */
const VENDOR_FILES = ["allw_wasm.js", "allw_wasm_bg.wasm"] as const;

/**
 * The most characters of a load failure's escaped cause that {@link wasmLoadError} quotes, before the
 * `...` that marks a clip.
 */
export const MAX_WASM_LOAD_CAUSE_CHARS = 200;

/**
 * A load failure's cause as one bounded line of printable ASCII ({@link escapeToPrintableAscii},
 * clipped to {@link MAX_WASM_LOAD_CAUSE_CHARS}). The display-escaping core is the thing that failed
 * to load, so it can't be used here. A cause can't move the cursor or spoof lines in a terminal or
 * a hook's deny reason.
 */
function describeLoadCause(cause: unknown): string {
  let text: string;
  try {
    text =
      cause instanceof Error
        ? `${cause.name}: ${cause.message}`
        : `non-error thrown: ${String(cause)}`;
  } catch {
    text = "a cause that could not be described";
  }
  return escapeToPrintableAscii(text, MAX_WASM_LOAD_CAUSE_CHARS);
}

/**
 * The actionable error for a vendored core that failed to load (#301). When a vendored file is
 * missing, the fix is to build it, and the message says so. Otherwise the files are there and
 * something else broke (a glue module that fails to evaluate, a corrupt `.wasm`), so the message
 * quotes the underlying cause, escaped and bounded, instead of sending the reader to rebuild.
 *
 * Exported for tests; not re-exported from the package entry point.
 *
 * @internal
 */
export function wasmLoadError(
  dir: string,
  cause: unknown,
  fileExists: (path: string) => boolean = existsSync,
): Error {
  const missing = VENDOR_FILES.filter((file) => !fileExists(join(dir, file)));
  // The vendor dir comes from the install location, which can hold any characters; it is quoted
  // escaped and bounded like the cause (#358).
  const shownDir = escapeToPrintableAscii(dir, MAX_ESCAPED_DIAGNOSTIC_CHARS);
  if (missing.length > 0) {
    return new Error(
      `allw: failed to load the vendored WASM core from ${shownDir}: ${missing.join(" and ")} ` +
        `${missing.length === 1 ? "is" : "are"} missing. Run \`pnpm run build:wasm\` from the ` +
        `repo root first (or reinstall @allw/sdk if it came from npm).`,
      { cause },
    );
  }
  return new Error(
    `allw: failed to load the vendored WASM core from ${shownDir} (${describeLoadCause(cause)}). ` +
      `The vendored files are present, so rebuilding may not help; reinstall @allw/sdk or ` +
      `rebuild the core (\`pnpm run build:wasm\`) if the files are damaged.`,
    { cause },
  );
}

/**
 * Load (and memoize) the vendored WASM core.
 *
 * @throws if the vendored core is missing (the message says to run `pnpm run build:wasm`) or
 *   fails to load (the message quotes the cause, escaped and bounded; see {@link wasmLoadError}).
 */
export async function loadWasm(): Promise<AllwWasm> {
  if (cached) return cached;
  const dir = vendorDir();
  try {
    // A bare path is not a valid ESM specifier on Windows (`C:\...`); use a file:// URL.
    const glue = (await import(pathToFileURL(join(dir, "allw_wasm.js")).href)) as WasmGlue;
    return initGlue(glue, dir);
  } catch (cause) {
    throw wasmLoadError(dir, cause);
  }
}

/**
 * Synchronous {@link loadWasm}, for callers with a synchronous config step (the integrator config
 * loader, and through it the hooks' `readConfig`). The `--target web` glue is an ES module with no
 * top-level await, so Node's `require(esm)` loads it synchronously; it shares Node's module cache
 * (and this memo) with {@link loadWasm}, so the core is instantiated once either way.
 *
 * @throws if the vendored core is missing (the message says to run `pnpm run build:wasm`) or
 *   fails to load (the message quotes the cause, escaped and bounded; see {@link wasmLoadError}).
 */
export function loadWasmSync(): AllwWasm {
  if (cached) return cached;
  const dir = vendorDir();
  try {
    const require = createRequire(import.meta.url);
    const glue = require(join(dir, "allw_wasm.js")) as WasmGlue;
    return initGlue(glue, dir);
  } catch (cause) {
    throw wasmLoadError(dir, cause);
  }
}
